fn main(){let r=Path::new(R);let d=Path::new(D);assert!(!d.exists());assert_eq!(read(r.join("host-remote/review.json"))["passed"],true);assert_eq!(read(r.join("decision.json"))["directional_screen_passed"],false);assert_eq!(read(r.join("termination-observed.json"))["Reservations"][0]["Instances"][0]["State"]["Name"],"terminated");assert!(read(r.join("volumes.json"))["Volumes"].as_array().unwrap().is_empty());assert!(r.join("bucket-removed.json").exists());assert!(!fs::read_dir(r).unwrap().any(|e|e.unwrap().file_name().to_string_lossy().ends_with(".secret.json")));let before=read(r.join("tools-result.json"));let after=read(r.join("tools-after-result.json"));for h in["2d0953085bf720a25efbe24f853e97d27b1f12f18a398255ff82cbafde254dad","ec8801a9ad7447f1805dea54d8cab0ad166ecd11d220f9048b2f00bee9bb4f82"]{assert!(before["StandardOutputContent"].as_str().unwrap().contains(h));assert!(after["StandardOutputContent"].as_str().unwrap().contains(h));}fs::create_dir_all(d.join("artifacts")).unwrap();fs::write(d.join("README.md"),include_str!("report.md")).unwrap();for f in["protocol.md","preparation-note.md","native-qualification.json","decision.json","ready.rs","runner.rs","independent.rs","cloud.rs","analyze.rs","host.rs","decision.rs","prepare.rs","repair.rs","tag-repair.rs","capture-prepare.rs","post-prepare.rs","pack.rs","publish.rs","build-plan.json","build-plan-v2.json","build-plan-v3.json","build-plan-v4.json","generic-plan.json","generic-plan-v2.json"]{fs::copy(r.join(f),d.join("artifacts").join(f)).unwrap();}fs::copy(r.join("host-remote/review.json"),d.join("artifacts/host-review.json")).unwrap();for f in["crates/zopro-core/src/solver.rs","crates/zopro-core/src/solver/sparse_poseidon/tests.rs"]{let output=Command::new("diff").args(["-u","--label",&format!("original/{f}"),"--label",&format!("candidate/{f}")]).arg(Path::new("/home/ubuntu/src/zk-tools/zopro").join(f)).arg(r.join("source").join(f)).output().unwrap();assert_eq!(output.status.code(),Some(1));let name=if f.ends_with("solver.rs"){"solver.patch"}else{"poseidon-tests.patch"};fs::write(d.join("artifacts").join(name),output.stdout).unwrap();}let a=fs::read(r.join("analysis.json")).unwrap();let mut child=Command::new("gzip").args(["-n","-c"]).stdin(Stdio::piped()).stdout(fs::File::create(d.join("artifacts/analysis.json.gz")).unwrap()).spawn().unwrap();child.stdin.take().unwrap().write_all(&a).unwrap();assert!(child.wait().unwrap().success());let activation=read(r.join("remote/output/jobs.json")).as_array().unwrap().iter().filter(|j|j["preflight"]==true&&j["arm"]=="ON").map(|j|{let name=j["name"].as_str().unwrap();let text=fs::read_to_string(r.join(format!("remote/output/preflight-run/{name}/stderr.log"))).unwrap();let rows=text.lines().filter(|l|l.starts_with("READY_SOLVER ")).collect::<Vec<_>>();json!({"name":name,"graph_trace":rows})}).collect::<Vec<_>>();fs::write(d.join("artifacts/activation.json"),serde_json::to_vec_pretty(&activation).unwrap()).unwrap();let mut files=fs::read_dir(d.join("artifacts")).unwrap().map(|e|format!("artifacts/{}",e.unwrap().file_name().to_str().unwrap())).collect::<Vec<_>>();files.push("README.md".into());files.sort();fs::write(d.join("SHA256SUMS"),files.iter().map(|f|format!("{}  {f}\n",hash(d.join(f)))).collect::<String>()).unwrap();println!("246 failed screen, positive contexts and memory limitation preserved; report/source written");}
